// At the same moment expiry beats cancellation: an abort arriving once the
// deadline has already passed settles as WAIT_EXPIRED. After the cut every
// other due expiry is settled (expiry before this cancellation), and a serve
// pass re-tries later entries so a withdrawn or rejected head never leaves
// the queue parked until the next window flip.
function onEntryAbort(entry) {
  if (entry.removed) return;
  const r = entry.qroot;
  if (entry.deadline <= rootNow(r)) {
    settleEntry(entry, 'expired');
  } else {
    settleEntry(entry, 'cancelled');
  }
  serveRoot(r);
}

