// leaves the queue parked until the next window flip.
function onEntryAbort(entry) {
  if (entry.removed) return;
  const r = entry.qroot;
  sweepExpiredAt(r, rootNow(r));
  if (!entry.removed) settleEntry(entry, 'cancelled');
