test('expiry, cancellation and a grant on the same cut settle in that order', async () => {
  const root = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000 });
  const soon = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 30, parent: root });
  await root.acquire(1); // pool 1/2
  const ac = new AbortController();
  const pExpiring = soon.acquire(1); // deadline t0+30; gathers the last unit and waits
  const pAborted = root.acquire(1, ac.signal); // long cap; cannot gather, queues
  let served = false;
  const pServed = root.acquire(1).then((h) => {
    served = true;
    return h;
  }); // also cannot gather yet; freed by this cut and served last
  await sleep(35); // past pExpiring's deadline, before any (10s) window flip
  ac.abort(); // same cut: the due head expires first, this abort cancels second
  await Promise.allSettled([pExpiring, pAborted]);
  assert.equal(soon.stats().expired, 1);
  assert.equal(root.stats().cancelled, 1);
  const hServed = await pServed; // serve pass runs after both settlements
  assert.equal(served, true);
  assert.equal(root.stats().granted, 2); // the original occupant plus the freed waiter
  assert.equal(root.stats().inFlight, 2); // the long window never flipped
  await assert.rejects(pExpiring, (err) => err.code === 'WAIT_EXPIRED');
  await assert.rejects(pAborted, (err) => err.code === 'CANCELLED');
  hServed.release();
});

