import { createGate, QuotaExceededError } from './src/index.js';

const sleep = (ms) => new Promise((res) => setTimeout(res, ms));
let failures = 0;
const check = (cond, msg) => {
  if (!cond) {
    failures += 1;
    console.error('FAIL:', msg);
  }
};

// Stress 1: random cancels with a very long window — queue must keep settling.
async function stressCancels() {
  const gate = createGate({ limit: 4, windowMs: 600000, maxWaitMs: 600000 });
  await gate.acquire(4);
  const acs = [];
  const ps = [];
  let granted = 0;
  let cancelled = 0;
  for (let i = 0; i < 40; i += 1) {
    const ac = new AbortController();
    acs.push(ac);
    const p = gate
      .acquire(1 + (i % 3), ac.signal)
      .then(() => {
        granted += 1;
      })
      .catch((e) => {
        check(e instanceof QuotaExceededError, 'stress1 QE');
        cancelled += 1;
      });
    ps.push(p);
  }
  // randomly cancel about half, spread over ticks
  const order = acs.map((_, i) => i).sort(() => Math.random() - 0.5);
  for (let k = 0; k < order.length; k += 1) {
    if (k % 2 === 0) acs[order[k]].abort();
    if (k % 3 === 0) await sleep(1);
  }
  await sleep(20);
  const s = gate.stats();
  check(granted + cancelled === 40, `stress1 all settled ${granted}/${cancelled}`);
  check(s.waiting === 0, 'stress1 waiting 0');
  check(s.granted === granted && s.cancelled === cancelled, 'stress1 counters');
  // nothing could be granted: pool fully occupied by a live handle, long window
  check(s.inFlight === 4, `stress1 inFlight stays 4 (got ${s.inFlight})`);
  check(s.reserved === 0, 'stress1 no leaked reservations');
}

// Stress 2: cancels freeing room actually grant held waiters without a flip.
async function stressFreedRoom() {
  const gate = createGate({ limit: 6, windowMs: 600000, maxWaitMs: 600000 });
  const h0 = await gate.acquire(3);
  const acs = [];
  const ps = [];
  const states = [];
  for (let i = 0; i < 12; i += 1) {
    const ac = new AbortController();
    acs.push(ac);
    const st = { g: false, c: false };
    states.push(st);
    ps.push(
      gate
        .acquire(1, ac.signal)
        .then((h) => {
          st.g = true;
          st.h = h;
        })
        .catch(() => {
          st.c = true;
        }),
    );
  }
  await sleep(5);
