          check(e instanceof QuotaExceededError, 'stress1 QE');
          cancelled += 1;
        }),
    );
  }
  const order = acs.map((_, i) => i);
  for (let k = order.length - 1; k > 0; k -= 1) {
    const j = Math.floor(Math.random() * (k + 1));
    [order[k], order[j]] = [order[j], order[k]];
  }
  for (const i of order) {
    acs[i].abort(); // pool never frees (live handle, no flip): everyone cancels
    if (i % 7 === 0) await sleep(1);
  }
  await Promise.all(ps);
  const s = gate.stats();
  check(granted === 0 && cancelled === 40, `stress1 settled g=${granted} c=${cancelled}`);
  check(s.waiting === 0, 'stress1 waiting 0');
  check(s.inFlight === 4, `stress1 inFlight 4 (got ${s.inFlight})`);
  check(s.reserved === 0, 'stress1 no leaked reservations');
}

// Cancelling a blocked combo head lets held later requests settle on the same
// cut (long window, no flip).
async function stressFreedRoom() {
  const gate = createGate({ limit: 6, windowMs: 600000, maxWaitMs: 600000 });
  await gate.acquire(3); // pool 3/6
  const headAc = new AbortController();
  // A 4-unit combo cannot gather (3+4>6): it is the blocked soft head and
  // holds nothing.
  const pHead = gate
    .acquireAll([{ gate, units: 4 }], headAc.signal)
    .then(
      () => 'granted',
      (e) => e.code,
    );
  const acs = [];
  const states = [];
  const ps = [];
  for (let i = 0; i < 5; i += 1) {
    const ac = new AbortController();
    acs.push(ac);
    const st = { g: false, c: false };
    states.push(st);
    ps.push(
      gate
        .acquire(1, ac.signal)
        .then((h) => {
          st.g = true;
          st.h = h;
        })
        .catch(() => {
          st.c = true;
        }),
    );
  }
  await sleep(5);
  check(states.every((x) => !x.g), 'stress2 nobody granted before the cut');
  check(gate.stats().reserved === 3, `stress2 three held units (got ${gate.stats().reserved})`);
  headAc.abort(); // withdraw the blocked head
  const headOutcome = await pHead;
  check(headOutcome === 'CANCELLED', `stress2 head cancelled (got ${headOutcome})`);
  await sleep(5);
  const grantedNow = states.filter((x) => x.g).length;
  check(grantedNow === 3, `stress2 head cancel granted 3 (got ${grantedNow})`);
  for (let i = 0; i < acs.length; i += 1) {
    if (!states[i].g && !states[i].c) acs[i].abort();
  }
  await Promise.all(ps);
  check(states.every((x) => x.g || x.c), 'stress2 all settled');
  check(gate.stats().reserved === 0, 'stress2 no leaked reservations');
  for (const st of states) if (st.h) st.h.release();
}

// Reparent while combos are queued and get aborted: no liveQueued/reservation
// leaks and accounting always closes.
async function stressReparent() {
  for (let iter = 0; iter < 30; iter += 1) {
    const oldRoot = createGate({ limit: 3, windowMs: 600000, maxWaitMs: 600000 });
    const a = createGate({ limit: 2, windowMs: 600000, maxWaitMs: 600000, parent: oldRoot });
    const b = createGate({ limit: 2, windowMs: 600000, maxWaitMs: 600000, parent: oldRoot });
    const newRoot = createGate({ limit: 2 + (iter % 4), windowMs: 30, maxWaitMs: 600000 });
    await oldRoot.acquire(3);
    const acs = [];
    const ps = [];
    for (let i = 0; i < 6; i += 1) {
      const ac = new AbortController();
      acs.push(ac);
      const member = i % 2 === 0 ? a : b;
      ps.push(oldRoot.acquireAll([{ gate: member, units: 1 }], ac.signal).catch((e) => e));
    }
    let moved = true;
    try {
      a.reparent(newRoot);
    } catch (e) {
      moved = false;
      check(e.code === 'QUOTA_EXCEEDED', 'stress3 reparent QE code');
    }
    for (let k = 0; k < acs.length; k += 1) {
      if (Math.random() < 0.5) acs[k].abort();
    }
    const results = await Promise.all(ps);
    for (const r of results) {
      check(
        r instanceof QuotaExceededError || typeof r.release === 'function',
        'stress3 settled value',
      );
    }
    const ors = oldRoot.stats();
    const nrs = newRoot.stats();
    check(ors.waiting === 0 && nrs.waiting === 0, 'stress3 no dangling waiting');
    check(ors.reserved === 0 && nrs.reserved === 0, 'stress3 no leaked reservations');
    const settled =
      ors.granted + ors.refused + ors.expired + ors.cancelled + nrs.granted + nrs.expired + nrs.cancelled;
    check(
      settled === 3 + 6,
      `stress3 accounting iter ${iter} moved=${moved}: ${JSON.stringify({ o: ors, n: nrs })}`,
    );
  }
}

await stressCancels();
await stressFreedRoom();
await stressReparent();
console.log(failures === 0 ? 'STRESS OK' : `STRESS FAILURES: ${failures}`);
process.exit(failures === 0 ? 0 : 1);

